<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use Illuminate\Support\Facades\DB;
class ActivityController extends Controller {public function overview(){ $u=request()->user();$dates=$u->moodCheckins()->selectRaw('DATE(checked_in_at) d')->distinct()->orderByDesc('d')->pluck('d')->map(fn($d)=>(string)$d);$streak=0;$cursor=today();foreach($dates as $d){if($d===$cursor->toDateString()){$streak++;$cursor->subDay();}elseif($streak===0&&$d===$cursor->copy()->subDay()->toDateString()){$streak++;$cursor->subDays(2);}else break;}return response()->json(['overview'=>['mood_checkins'=>$u->moodCheckins()->count(),'journals'=>$u->journals()->count(),'coping_actions'=>DB::table('mood_checkin_coping_mechanisms')->join('mood_checkins','mood_checkins.id','=','mood_checkin_id')->where('mood_checkins.user_id',$u->id)->count(),'current_streak'=>$streak]]);} public function moodChart(){ $days=max(1,min((int)request('days',7),365));$rows=request()->user()->moodCheckins()->with('feelingExpression.feeling')->where('checked_in_at','>=',now()->subDays($days-1)->startOfDay())->orderBy('checked_in_at')->get()->map(fn($m)=>['date'=>$m->checked_in_at->toDateString(),'intensity'=>$m->intensity,'feeling'=>$m->feelingExpression?->feeling?->name,'expression'=>$m->feelingExpression?->name]);return response()->json(['chart'=>$rows]);} public function triggers(){ $u=request()->user();$rows=DB::table('mood_checkin_causes')->join('mood_checkins','mood_checkins.id','=','mood_checkin_id')->join('feeling_causes','feeling_causes.id','=','feeling_cause_id')->where('mood_checkins.user_id',$u->id)->groupBy('feeling_causes.id','feeling_causes.name')->select('feeling_causes.id','feeling_causes.name',DB::raw('COUNT(*) count'))->orderByDesc('count')->limit(10)->get();return response()->json(['triggers'=>$rows]);} public function journalStats(){ $u=request()->user();return response()->json(['stats'=>['total'=>$u->journals()->count(),'this_week'=>$u->journals()->whereBetween('entry_date',[now()->startOfWeek(),now()->endOfWeek()])->count(),'this_month'=>$u->journals()->whereMonth('entry_date',now()->month)->whereYear('entry_date',now()->year)->count(),'latest_entry_date'=>optional($u->journals()->latest('entry_date')->first())->entry_date?->toDateString()]]);} public function recommendations(){return response()->json(['recommendations'=>[['title'=>'Take a mindful pause','description'=>'Spend two minutes breathing slowly and noticing what you feel.','type'=>'coping'],['title'=>'Write one honest sentence','description'=>'Capture what is on your mind without judging it.','type'=>'journal']]]);}}
